const PEOPLE=[{name:'서윤',role:'현장을 먼저 보는 선배',letter:'윤',color:'#59765d'},{name:'도현',role:'함께 발령받은 동기',letter:'현',color:'#b66d44'},{name:'은별',role:'새봄학교 현장 지원',letter:'별',color:'#5c7d88'}];
let s=null,sound=false,ac=null,home=true,lastFocus=null,saveFailed=false,toastTimer;
let eventOpen=false,interactionHTML='',autoMode=false,autoDelay=3000,autoTimer=null;
function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){let j=random(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function valid(x){return !!(x&&x.version===2&&typeof x.name==='string'&&Number.isInteger(x.dept)&&x.dept>=0&&x.dept<6&&Number.isInteger(x.step)&&x.step>=0&&x.step<=10&&['appointment','play','result','transfer','end'].includes(x.phase)&&x.local&&Array.isArray(x.local.pick)&&Array.isArray(x.local.path)&&Array.isArray(x.local.order)&&Array.isArray(x.local.open)&&Array.isArray(x.log)&&Array.isArray(x.route)&&Array.isArray(x.visits)&&x.flags&&Array.isArray(x.city)&&x.city.length===3&&Array.isArray(x.bag)&&typeof x.energy==='number'&&typeof x.trust==='number'&&Number.isInteger(x.first)&&x.first>=0&&x.first<6)}
function load(){try{const x=JSON.parse(localStorage.getItem(SAVE_KEY));if(!valid(x))return null;if(x.phase==='transfer'){x.phase='play';x.local=blank()}if(x.phase!=='appointment'){x.dept=x.first;x.route=[{dept:x.first,day:1}]}return x}catch{return null}}
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(s))}catch{saveFailed=true}}
function setChrome(mode){const w=document.querySelector('.wrap');if(!w)return;w.classList.toggle('chrome-home',mode==='home');w.classList.toggle('chrome-focus',mode==='focus')}
function toast(t){$('live').textContent=t;document.querySelector('.toast')?.remove();clearTimeout(toastTimer);const e=document.createElement('div');e.className='toast';e.textContent=t;document.body.appendChild(e);toastTimer=setTimeout(()=>e.remove(),3300)}
function beep(good=false){if(!sound)return;try{ac??=new(window.AudioContext||window.webkitAudioContext)();ac.resume();const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.setValueAtTime(good?640:410,ac.currentTime);o.frequency.exponentialRampToValueAtTime(good?960:530,ac.currentTime+.13);g.gain.setValueAtTime(.035,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.21);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.22)}catch{}}
function toggleSound(){sound=!sound;$('sound').textContent=sound?'소리 켜짐':'소리 꺼짐';$('sound').setAttribute('aria-pressed',sound);beep()}
function modal(title,body){lastFocus=document.activeElement;$('overlay').innerHTML=`<div class="modal-back" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="mt"><button class="close" aria-label="닫기" onclick="closeModal()">×</button><span class="label muted">오늘부터 조달청 / STORY EDITION</span><h2 id="mt">${title}</h2>${body}</section></div>`;document.body.style.overflow='hidden';$('overlay').querySelector('button').focus()}
function closeModal(){eventOpen=false;$('overlay').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus()}
function talk(who,text){const p=PEOPLE[who];return `<div class="dialogue"><div class="portrait" style="--portrait:${p.color}">${p.letter}<span></span></div><div><span class="label">${p.name} <small class="muted">${p.role}</small></span><p>${text}</p></div></div>`}
function cityArt(){const c=s?.city||[0,0,0],night=s?.phase==='end';return `<svg viewBox="0 0 760 340" role="img" aria-label="선택에 따라 학교, 공장, 문화관 불이 켜지는 가상의 도시"><rect width="760" height="340" fill="${night?'#263f3e':'#dfe9dc'}"/><circle cx="665" cy="55" r="24" fill="${night?'#fff1c0':'#e8b667'}"/><path d="M0 210Q100 150 240 200T760 185V340H0" fill="${night?'#365b4a':'#becfb3'}"/><path d="M0 285H760" stroke="${night?'#51695d':'#a8b8a4'}" stroke-width="39"/><path d="M0 285H760" stroke="#e9eddc" stroke-dasharray="20 22" stroke-width="2"/>${[90,310,550].map((x,i)=>`<g transform="translate(${x},${i===1?142:158})"><rect width="145" height="103" fill="${['#d39b70','#a3b79b','#e3d9b7'][i]}"/>${i===1?'<path d="M0 0L35-30V0L80-30V0L120-30V0" fill="#668369"/><rect x="105" y="-60" width="15" height="40" fill="#668369"/>':`<path d="M-10 0L72-42L155 0Z" fill="${i===0?'#a25d41':'#557561'}"/>`}${[17,57,97].map(xx=>`<rect x="${xx}" y="25" width="28" height="29" rx="2" fill="${c[i]>0?'#ffdf87':'#748f82'}"/>`).join('')}<rect x="61" y="70" width="25" height="33" fill="#3c5d4b"/><text x="72" y="19" text-anchor="middle" font-size="12" font-weight="bold" fill="#284238">${['새봄학교','산업단지','모아문화관'][i]}</text><text x="72" y="127" text-anchor="middle" font-size="11" fill="${night?'#e6edda':'#385343'}">${c[i]>=4?'다시 살아난 일상':c[i]>=2?'준비가 이어지는 중':c[i]>0?'첫 불이 켜졌어요':'아직은 조용한 곳'}</text></g>`).join('')}<g transform="translate(${80+(s?.step||0)*47},272)"><rect width="41" height="20" rx="3" fill="#c56f47"/><path d="M41 2h17l6 8v10H41Z" fill="#edb66d"/><rect x="45" y="5" width="11" height="8" fill="#e9efdd"/><circle cx="10" cy="23" r="6" fill="#2d4a3e"/><circle cx="52" cy="23" r="6" fill="#2d4a3e"/></g><text x="30" y="35" font-size="10" letter-spacing="3" fill="${night?'#c5d7bd':'#5c775a'}">가상의 도시 / 게임 이야기</text><path d="M260 62h55m-27-17v34M451 95h20" stroke="#adc3a4" stroke-width="2"/></svg>`}
function mascotWelcome(compact=false){return `<div class="mascot-welcome ${compact?'compact':''}"><img src="${BRAND_ASSETS.characters}" alt="조달청 캐릭터 나르미와 달이" width="3394" height="2304"><div><span class="label">나르미 &amp; 달이</span><p>${compact?'첫 출근, 화이팅!':'발령 축하해요. 현장부터 같이 가요!'}</p></div></div>`}
function landingVoice(){return `<div class="landing-voice"><img src="${BRAND_ASSETS.characters}" alt="나르미와 달이" width="3394" height="2304"><div><span class="label">나르미 &amp; 달이</span><p>“개학 전인데 운동장에 문제가 있어요.<br>같이 확인해 볼까요?”</p><span class="fine">가상 이야기예요 · 실제 조달청이랑은 달라요.</span></div></div>`}
function landing(){pauseAuto();eventOpen=false;home=true;setChrome('home');const old=load();$('app').innerHTML=`<section class="screen"><div class="hero"><div><div class="eyebrow"><span class="dot"></span> STORY EDITION 05 / 나르미·달이와 첫 출근</div><h1>오늘부터 조달청,<br>첫 발령받은<br><span>아침이에요.</span></h1><p class="desc">발령 받는 날, 벌써 전화가 와요.<br>학교·공장·문화관이 한꺼번에 바쁜 30일,<br>어느 책상에 앉든 한 부서 이야기를 가볍게 이어 가 보세요.</p><div class="hero-actions"><button class="btn" onclick="newGame()">새로운 발령 받기 ↗</button>${old?'<button class="btn outline" onclick="resume()">이야기 이어하기 →</button>':''}</div><p class="fine">대략 10~15분</p><div class="hero-meta"><div><b>06</b><span>랜덤 발령 부서</span></div><div><b>10</b><span>서로 다른 장면</span></div></div></div><div class="scene story-scene">${cityArt()}${landingVoice()}</div></div><div class="division"><span class="label">어떤 사람이 되어 돌아올까요?</span><span class="muted" style="font-size:12px">발령은 우연, 선택은 당신 몫</span></div><div class="dept-grid six">${DEPTS.map((d,i)=>`<article class="dept-card"><span class="number">${d.icon} &nbsp; 0${i+1} / ${d.org}</span><h3>${d.name}</h3><p>${d.desc}</p><span class="activity">${d.tag}</span></article>`).join('')}</div></section>`}
function blank(){return {pick:[],open:[],path:[0],order:[],selected:null,feedback:'',tries:0,tool:false}}
function newGame(){if(load())return modal('새로운 이야기를 시작할까요?','<p>진행 중인 이야기는 새로 시작합니다.</p><div class="row"><button class="btn" onclick="closeModal();createGame()">새 발령 받기</button><button class="btn outline" onclick="closeModal();resume()">이어하기</button></div>');createGame()}
function createGame(){s={version:2,name:'신입',dept:random(6),first:0,step:0,phase:'appointment',rerolled:false,energy:6,trust:2,city:[0,0,0],flags:{},bag:[],visits:[],route:[],log:[],local:blank(),seed:random(10000),weather:random(2),sourceSeen:[]};save();render();beep(true)}
function resume(){s=load();eventOpen=!!(s&&s.phase==='play');if(s)render();else toast('저장된 이야기가 없습니다.')}
function reroll(){if(s.phase!=='appointment'||s.rerolled)return;s.name=($('name').value.trim()||'신입').slice(0,12);s.dept=(s.dept+1+random(5))%6;s.rerolled=true;save();render()}
function appointment(){const d=DEPTS[s.dept];$('app').innerHTML=`<section class="center screen"><div class="appointment">${mascotWelcome(true)}<div class="row space"><span class="label">PERSONNEL NOTICE / ${String(s.seed).padStart(4,'0')}</span><span class="seal">발령 완료</span></div><h1>당신의 이야기는<br>여기서 시작됩니다.</h1><span class="label muted">첫 번째 책상 / ${d.org}</span><h2 class="dept-name">${d.name}</h2><p class="muted">${d.desc}</p><div class="perk"><b>${d.perk}</b><span>${d.help}</span></div>${talk(0,d.line)}<label class="field" for="name">명찰에 적을 이름</label><input id="name" type="text" maxlength="12" value="${esc(s.name==='신입'?'':s.name)}" placeholder="별명도 좋아요" autocomplete="off"><div class="row" style="margin-top:24px"><button class="btn" onclick="begin()">첫 출근하기 →</button><button class="btn outline" onclick="reroll()" ${s.rerolled?'disabled':''}>${s.rerolled?'재추첨 사용 완료':'다시 추첨 · 한 번'}</button></div><p class="notice">30일의 프로젝트와 발령은 게임을 위한 가상 설정입니다.</p></div></section>`}
function begin(){if(s.phase!=='appointment')return;s.name=($('name').value.trim()||'신입').slice(0,12);s.first=s.dept;s.route=[{dept:s.dept,day:1}];if(s.dept===0)s.energy++;if(s.dept===1)s.flags.observer=true;if(s.dept===2)s.bag.push('여유 물량');if(s.dept===3)s.flags.innovation=true;if(s.dept===4)s.flags.access=true;if(s.dept===5)s.trust++;s.phase='play';eventOpen=true;save();render()}
function render(scroll=true){home=false;setChrome(s.phase==='end'||s.phase==='appointment'||s.phase==='play'||s.phase==='result'?'focus':'home');if(s.phase==='appointment')appointment();else if(s.phase==='play')play();else if(s.phase==='result')result();else if(s.phase==='transfer')transfer();else ending();if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function apply(e={}){s.energy=clamp(s.energy+(e.energy||0),0,10);s.trust=clamp(s.trust+(e.trust||0),0,8);if(e.city)e.city.forEach((n,i)=>s.city[i]=clamp(s.city[i]+n,0,8));if(e.flag)s.flags[e.flag]=true;if(e.bag&&!s.bag.includes(e.bag))s.bag.push(e.bag)}
function finish(title,text,effect={},source=11){if(s.phase!=='play')return;closeModal();apply(effect);s.log.push({step:s.step,day:DAYS[s.step],dept:s.dept,title,text,effect,source});s.phase='result';save();render();beep(true)}
function advance(){if(s.phase!=='result')return;s.step++;s.local=blank();if(s.step>=10)s.phase='end';else s.phase='play';eventOpen=s.phase==='play';save();render();beep()}
function departmentForMini(){return s.dept}
function stats(){return `<div class="meters"><div><span>나의 여유</span><b>${'●'.repeat(Math.ceil(s.energy/2))}<i>${'○'.repeat(5-Math.ceil(s.energy/2))}</i></b><small>${s.energy}/10</small></div><div><span>동료 신뢰</span><b>${s.trust}<small> / 8</small></b></div></div>`}
function shell(content){
 interactionHTML=content;
 const isResult=s.phase==='result',entry=s.log.at(-1);
 const summaries=['학교, 공장, 문화관. 먼저 누구 이야기를 들을까요?','지도에서 두세 곳만 고를 수 있어요. 오늘 걸은 길이 나중에 도움이 됩니다.','교실 밖 현장 일이에요. 맞춰 보고 막히면 동료에게 물어도 돼요.','동기 도현이 점심 같이 먹자고 해요.','같은 부서에서 또 다른 일이 왔어요.','갑자기 내린 비로 일정이 흔들려요. 예전에 메모해 둔 게 떠오를 수 있어요.','기업 문의 세 통. 맞는 안내 창구를 연결해 주세요.','시간이 조금 남았어요. 마음 가는 데 하나 더 손볼까요?','내일 문 여는 날이에요. 마지막으로 무엇부터 할지 고릅니다.','퇴근길에, 우리가 도운 곳을 잠깐 들러 볼까요?'];
 $('app').innerHTML=`<section class="screen compact-game"><div class="play-toolbar"><div><span class="label">DAY ${DAYS[s.step]||30} / 30</span><b>${DEPTS[s.dept].name}</b></div><div class="play-controls"><button class="btn small ${autoMode?'light':'outline'}" onclick="toggleAuto()" aria-pressed="${autoMode}">${autoMode?'Ⅱ 자동 진행 멈춤':'▶ 랜덤 자동 진행'}</button><label class="sr" for="pace">자동 진행 속도</label><select id="pace" onchange="setPace(this.value)"><option value="5000" ${autoDelay===5000?'selected':''}>느긋하게</option><option value="3000" ${autoDelay===3000?'selected':''}>보통</option><option value="1200" ${autoDelay===1200?'selected':''}>빠르게</option></select></div></div><div class="story-layout"><aside class="story-aside"><div class="mini-id"><div class="avatar">${esc(s.name.slice(0,1))}</div><div><h3>${esc(s.name)}</h3><small>${DEPTS[s.first].perk}</small></div></div>${stats()}<div class="side-heading">나의 도구함</div><div class="toolbag">${s.bag.length?s.bag.map(x=>`<span class="chip">${esc(x)}</span>`).join(''):'<p class="fine">사람을 만나면 단서가 생깁니다.</p>'}</div><button class="log-btn" onclick="showLog()">나의 이야기 기록 ↗</button><button class="log-btn" onclick="showSources()">조달청 탐험 노트 ↗</button></aside><div class="story-main"><div class="city-strip"><p class="city-map-caption">가상 도시 한눈에 · 학교·공장·문화관은 떨어진 현장이지만, 선택에 따라 불이 켜집니다.</p>${cityArt()}<div class="city-status">${CITY_SITES.map((n,i)=>`<span>${n} <b>${s.city[i]>=4?'활기':s.city[i]>=2?'준비 중':s.city[i]>0?'첫 변화':'조용함'}</b></span>`).join('')}</div><article class="paper story-preview"><div class="preview-top"><span class="chip">${isResult?'선택의 결과':KINDS[s.step]}</span><span class="label muted">SCENE ${s.step+1} / 10</span></div><h2>${isResult?entry.title:TITLES[s.step]}</h2><p>${isResult?entry.text:summaries[s.step]}</p>${isResult?`<div class="effect-chips">${effectText(entry.effect)}</div>`:''}<div class="fixed-decisions">${isResult?`<button class="btn full" onclick="advance()">${s.step===9?'나의 엔딩 보기 →':'다음 장면으로 →'}</button><button class="text-button" onclick="openDetail()">장면 자세히 보기</button>`:`<button class="btn full" onclick="openEvent()">${s.step===1?'지도 펼쳐 보기':s.step===2||s.step===4?'현장 일 시작하기':'이야기 속에서 고르기'} →</button>`}</div></article><div class="compact-status">여유 ${s.energy}/10 · 동료 신뢰 ${s.trust}/8 <span>${autoMode?'자동 진행 중 · 언제든 멈출 수 있어요':'선택은 팝업에서 · 자동 저장'}</span></div></div></div></section>`;
 if(eventOpen&&s.phase==='play')showEventDialog();
}
function openDetail(){pauseAuto();modal('이번 장면 자세히 보기',interactionHTML)}
function openEvent(){if(s.phase!=='play')return;eventOpen=true;showEventDialog()}
function showEventDialog(){
 const scroll=$('overlay').querySelector('.event-scroll')?.scrollTop||0;
 lastFocus=document.activeElement;
 $('overlay').innerHTML=`<div class="modal-back event-back"><section class="event-dialog" role="dialog" aria-modal="true" aria-labelledby="event-title"><div class="event-bar"><span id="event-title">${KINDS[s.step]} · DAY ${DAYS[s.step]}</span><div>${autoMode?'<button onclick="toggleAuto()">Ⅱ 자동 진행 멈춤</button>':''}<button onclick="closeModal()" aria-label="선택 팝업 닫기">×</button></div></div><div class="event-scroll">${interactionHTML}</div><div class="event-foot"><span>${autoMode?'동료가 대신 고르는 중이에요.':'천천히 해도 돼요. 시간 제한 없어요.'}</span><button onclick="closeModal();toggleAuto()">${autoMode?'자동 진행 멈추기':'동료에게 맡기고 자동 진행'}</button></div></section></div>`;
 document.body.style.overflow='hidden';
 const sc=$('overlay').querySelector('.event-scroll');if(sc)sc.scrollTop=scroll;
 $('overlay').querySelector('button').focus();
}
function pauseAuto(){autoMode=false;clearTimeout(autoTimer);autoTimer=null}
function queueAuto(){clearTimeout(autoTimer);if(autoMode)autoTimer=setTimeout(()=>{autoStep();queueAuto()},autoDelay)}
function toggleAuto(){if(!s||['appointment','end'].includes(s.phase))return;autoMode=!autoMode;if(autoMode)queueAuto();else clearTimeout(autoTimer);if(s.phase==='play'||s.phase==='result')render(false);else if(s.phase==='transfer')transfer()}
function setPace(v){autoDelay=[1200,3000,5000].includes(Number(v))?Number(v):3000;if(autoMode)queueAuto()}
function autoStep(){
 if(!autoMode||!s)return;
 if(s.phase==='end'){pauseAuto();return}
 if(s.phase==='result'){advance();return}
 if(s.phase==='transfer'){moveDept(random(6));return}
 if(s.phase!=='play')return;
 if(s.step===0)introChoice(['school','factory','culture'][random(3)]);
 else if(s.step===1){const left=PLACES.map((_,i)=>i).filter(i=>!s.visits.includes(i));if(s.visits.length<(s.flags.observer?3:2))visit(left[random(left.length)]);else finishField()}
 else if(s.step===4)departmentChoice(random(3));else if(s.step===2){s.local.tries=2;s.local.tool=true;teamFinish()}
 else if(s.step===3)lunchChoice(random(3));
 else if(s.step===5){const choices=[2];if(s.flags.rain||s.flags.harbor)choices.push(0);if(s.bag.includes('여유 물량')||s.trust>=4)choices.push(1);crisisChoice(choices[random(choices.length)])}
 else if(s.step===6){s.local.order=[0,1,2];submitCalls()}
 else if(s.step===7)projectChoice(random(3));
 else if(s.step===8){let cost=0;s.local.pick=[];for(const i of shuffle([0,1,2,3,4])){if((!OPS[i].trust||s.trust>=OPS[i].trust)&&cost+OPS[i].cost<=opBudget()){s.local.pick.push(i);cost+=OPS[i].cost}}submitOps()}
 else if(s.step===9)finaleChoice(random(3));
}

function title(sub,title,desc){return `<div class="paper-header"><div class="row space"><span class="chip">${sub}</span><span class="label muted">DAY ${DAYS[s.step]}</span></div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>`}
function choice(text,sub,fn,disabled=false){return `<button class="story-choice" onclick="${fn}" ${disabled?'disabled':''}><span>${text}</span><small>${sub}</small><b>↗</b></button>`}
function play(){if(s.step===0)intro();else if(s.step===1)field();else if(s.step===2)mini();else if(s.step===4)departmentStory();else if(s.step===3)lunch();else if(s.step===5)crisis();else if(s.step===6)routing();else if(s.step===7)project();else if(s.step===8)finalPlan();else finale()}
function intro(){shell(title('첫 만남','개학까지 남은 30일','세 곳 현장 준비를 돕는 일부터 시작해요.')+`<div class="paper-body">${talk(2,'새봄학교는 장비 점검 중이고, 산업단지는 원자재가 늦어지고 있어요. 문화관은 재개관 준비 중이에요. 한 달 동안 현장에서 무엇이 막히는지 듣고 연결해 주면 됩니다.')}${talk(0,'먼저 전화라도 한 통 해볼까요? 어디부터 들어볼래요?')}<div class="choice-stack">${choice('학교 선생님에게 전화한다','아이들의 하루부터 · 학교 단서 획득',"introChoice('school')")}${choice('산업단지 현장 담당자를 만난다','멈춘 생산라인부터 · 공급망 단서 획득',"introChoice('factory')")}${choice('문화관을 직접 걸어 본다','누구나 들어갈 수 있는지 · 접근성 단서 획득',"introChoice('culture')")}</div></div>`)}
function introChoice(id){const opts={school:['학교 장비의 전원 문제를 확인했습니다','선생님에게 확인하니, 새 장비를 설치할 교실에 전원 연결이 부족했습니다. 장비만 납품해서는 사용할 수 없으므로 학교 시설 담당자와 설치 조건을 함께 확인하기로 했습니다.',{flag:'school',city:[1,0,0],bag:'교실 현장 메모'}],factory:['원자재 납기 지연을 확인했습니다','현장 담당자는 원자재 도착이 늦어져 생산 일정이 밀릴 수 있다고 설명했습니다. 현재 재고와 필요한 시점을 확인하고 대체 공급 가능성을 검토하기로 했습니다.',{flag:'harbor',city:[0,1,0],bag:'대체 물류 연락망'}],culture:['도면에 없던 작은 턱','휠체어 바퀴가 입구의 턱 앞에서 멈췄습니다. 행사장의 모습보다, 들어갈 수 있는 길부터 살피기로 했습니다.',{flag:'access',city:[0,0,1],bag:'현장 동선 스케치'}]};const o=opts[id];if(o)finish(o[0],o[1],o[2],id==='factory'?2:id==='culture'?4:0)}
const PLACES=[
{name:'새봄학교',x:20,y:35,icon:'▱',quote:'“비가 오면 현관 바닥에 물이 고여요.”',detail:'선생님이 장화 자국을 가리켰습니다. 야외 장비와 현관을 위한 우천 대비 기록을 얻었습니다.',flag:'rain',bag:'우천 대비 메모',source:0},
{name:'작은 실험실',x:72,y:27,icon:'✦',quote:'“센서가 사람을 가방으로 착각했어요.”',detail:'밝은 곳에서만 시험한 센서였습니다. 어두운 현장 시험이라는 아이디어를 얻었습니다.',flag:'innovation',bag:'현장 실험 노트',source:3},
{name:'항구 전망대',x:34,y:73,icon:'≈',quote:'“다리가 막혀도, 돌아가는 길은 있어요.”',detail:'현장 담당자가 산길 우회로와 연락처를 적어줬습니다. 필요할 때 쓸 수 있을 것 같습니다.',flag:'harbor',bag:'대체 물류 연락망',source:2},
{name:'오래된 문화관',x:79,y:72,icon:'⌑',quote:'“이 문은 반대편에서만 열려요.”',detail:'관람객이 움직이는 길을 직접 걸었습니다. 도면의 선이 실제 동선이 되는 순간입니다.',flag:'access',bag:'현장 동선 스케치',source:4}
];
function field(){const max=s.flags.observer?3:2;const selected=s.visits.at(-1);shell(title('현장 탐색','지도에 없는 것들',`오늘은 ${max}곳까지만 갈 수 있어요. 어디를 가느냐에 따라 나중 일이 달라져요.`)+`<div class="paper-body"><div class="field-map"><div class="map-river"></div><div class="map-road"></div><span class="map-caption">현장 메모</span>${PLACES.map((p,i)=>`<button class="map-pin ${s.visits.includes(i)?'visited':''}" style="left:${p.x}%;top:${p.y}%" onclick="visit(${i})" ${!s.visits.includes(i)&&s.visits.length>=max?'disabled':''}><b>${s.visits.includes(i)?'✓':p.icon}</b><span>${p.name}</span></button>`).join('')}</div><p class="hint">${s.visits.length}/${max}곳 방문 · 장소를 눌러 이야기를 들어보세요.</p>${selected!==undefined?talk(2,PLACES[selected].quote)+`<div class="feedback">${PLACES[selected].detail}</div>`:talk(1,'오늘은 우리 둘이 나가는 거죠? 저 길을 한 번 돌아보고 싶었어요.')}<button class="btn" style="width:100%" onclick="finishField()" ${s.visits.length<max?'disabled':''}>현장 노트를 챙겨 돌아가기 →</button></div>`)}
function visit(i){if(s.phase!=='play'||s.step!==1||!PLACES[i])return;if(s.visits.includes(i)){toast(PLACES[i].quote);return}if(s.visits.length>=(s.flags.observer?3:2))return;s.visits.push(i);apply({flag:PLACES[i].flag,bag:PLACES[i].bag});save();play();beep()}
function finishField(){if(s.visits.length<(s.flags.observer?3:2))return;finish('발로 쓴 현장 노트',`${s.visits.map(i=>PLACES[i].name).join(', ')}에서 돌아왔습니다. 오늘 만난 사람들의 말이, 나중에 중요한 선택지를 열어 줄 겁니다.`,{energy:-1,trust:1},PLACES[s.visits[0]].source)}

const DEPT_STORIES=[
 ['개학 전날, 자리가 바뀌었다','학교에서 안내 장비 설치 위치를 바꾸고 싶대요. 시간이 별로 없어요.',['현장에서 진짜 필요한 것부터 다시 확인한다','동료랑 설치 조건을 나눠 본다','작게 달아 보고 반응을 듣는다']],
 ['포장은 멀쩡한데, 기록만 안 맞는다','상자는 깨끗한데 납품 목록이랑 현장 메모가 서로 달라요.',['현물이랑 목록을 하나씩 맞춰 본다','관련 담당자한테 서로 다른 기록을 물어본다','확실한 것이랑 애매한 것을 나눠 적는다']],
 ['제한 시간 14일','산업단지 두 곳에서 원자재 지원 요청이 들어왔어요. 남은 기한은 14일이고, 급한 정도는 현장마다 달라요.',['각 현장 재고랑 필요한 날짜를 확인한다','동료랑 공급 일정 대안을 얘기한다','당장 쓸 양이랑 나중 수요를 나눠 본다'],['3일 소요 · 두 현장 재고·납기일 확인','5일 소요 · 공급 일정 대안 맞추기','2일 소요 · 급한 물량부터 배분']],
 ['실험실에선 됐는데','복도에선 센서 반응이 달라요. 다음 시험을 어떻게 할까요?',['이용자를 만나서 불편한 점을 듣는다','개발사랑 조건 바꿔 가며 원인을 찾는다','작은 구역에서 돌려보고 적어 둔다']],
 ['도면엔 빈 칸이 없는데','문화관 도면에 대기 공간이 부족하대요. 예산도 같이 봐야 해요.',['동선부터 따라가 본다','설계 담당자랑 비용·공간 대안을 비교한다','바쁜 시간대 이용 상황을 살펴본다']],
 ['예약 첫날, 같은 질문만','문화관 예약 화면에 똑같은 문의가 쏟아졌어요.',['사람들이 실제로 누르는 순서를 본다','담당자랑 요구사항을 다시 정리한다','작은 화면 수정안을 같이 써 봤다']]
];
const DEPT_CHOICE_SUB=['시간 쓰고 현장을 깊게 본다.','동료랑 맞춰 보며 신뢰를 쌓는다.','작게 시험하고 메모해 둔다.'];
const DEPT_CHOICE_TAIL=['현장에서 뭐가 급한지 윤곽이 잡혔어요.','함께 본 내용이 다음 일에 넘어갔어요.','짧게 시험한 결과가 메모에 남았어요.'];
const DEPT_CHOICE_TAIL_BY_DEPT={2:['3일 동안 재고와 필요 날짜를 맞춰 뒀어요.','5일 동안 공급 일정 대안이 정리됐어요.','2일 만에 급한 물량부터 나눠 뒀어요.']};
function departmentStory(){const e=DEPT_STORIES[s.dept],subs=e[3]||DEPT_CHOICE_SUB;const hint=s.dept===2?'남은 14일 안에 무엇부터 할지 고르세요. 선택마다 소요 일수가 달라요.':'같은 부서에서 들어온 두 번째 일이에요. 어떻게 가느냐에 따라 나중 장면이 달라집니다.';shell(title(DEPTS[s.dept].name,e[0],e[1])+`<div class="paper-body"><div class="choice-grid">${e[2].map((t,i)=>`<button onclick="departmentChoice(${i})"><h3>${t}</h3><p>${subs[i]}</p></button>`).join('')}</div><p class="hint">${hint}</p></div>`)}
function departmentChoice(i){if(s.phase!=='play'||s.step!==4||![0,1,2].includes(i))return;const e=DEPT_STORIES[s.dept],city=[0,0,0];city[s.dept===2?1:s.dept>=4?2:0]=i===0?2:1;const tail=(DEPT_CHOICE_TAIL_BY_DEPT[s.dept]||DEPT_CHOICE_TAIL)[i];finish(e[0],e[2][i]+'. '+tail,{energy:i===0?-1:0,trust:i===1?2:0,city,bag:i===2?'추가 현장 기록':undefined},DEPTS[s.dept].source)}

function miniIntro(k){return {kit:'운동장에 보낼 물건을 골라 보는 일이에요. 고르기 전까지는 언제든 바꿀 수 있어요.',inspect:'상자 라벨을 하나씩 열어보는 일이에요. 마음 바뀌면 다시 고르면 돼요.',route:'창고에서 공장까지 갈 길을 이어 보는 일이에요.',test:'현장에서 겪은 증상을 재현할 시험 두 가지를 고르는 일이에요.',path:'입구에서 홀까지 지나갈 길을 그려 보는 일이에요.',order:'예약 화면을 고칠 때, 어떤 순서가 맞는지 맞춰 보는 일이에요.'}[k]}
function mini(){const d=DEPTS[departmentForMini()];const partner=s.step===4&&s.dept===s.first;let content='';if(d.kind==='kit')content=kit();if(d.kind==='inspect')content=inspect();if(d.kind==='route')content=route();if(d.kind==='test')content=testLab();if(d.kind==='path')content=pathGame();if(d.kind==='order')content=orderGame();shell(title(partner?'다른 부서에서 온 부탁':d.name,miniTitle(d.kind),partner?'옆 부서 동료가 도와달라고 왔어요. 잠깐 맡아 보는 일입니다.':miniIntro(d.kind))+`<div class="paper-body">${content}${s.local.feedback?`<div class="feedback puzzle-feedback" role="status">${s.local.feedback}</div>`:''}<p class="hint">${s.energy<3?'오늘은 좀 지쳐 보이네요. 힌트 받아도 괜찮아요.':'헷갈리면 동료에게 물어보세요. 한번 틀려도 이야기는 이어집니다.'}</p><button class="log-btn" onclick="puzzleHint()">동료에게 물어보기</button>${s.local.tries>=2?'<button class="btn outline small" onclick="teamFinish()">동료와 같이 마무리하기 →</button>':''}</div>`)}
function miniTitle(k){return {kit:'개학 전날, 운동장 안내',inspect:'상자 라벨이 하나 이상해요',route:'다리가 잠기기 전에',test:'센서가 가방을 사람으로 봐요',path:'이 길로 들어갈 수 있을까요',order:'예약 화면, 어디부터 고칠까요'}[k]}
const SUPPLIES=[{name:'방수 덮개',cost:2,tags:['비'],icon:'☂'},{name:'보조 전원',cost:3,tags:['전원'],icon:'ϟ'},{name:'안내 스피커',cost:2,tags:['안내'],icon:'◖'},{name:'대형 화면',cost:5,tags:['안내'],icon:'▣'},{name:'장식 조명',cost:2,tags:['장식'],icon:'✧'},{name:'다기능 안내함',cost:4,tags:['안내','비'],icon:'▤'}];
function kit(){const items=s.local.pick.map(i=>SUPPLIES[i]),cost=items.reduce((a,b)=>a+b.cost,0);return `${talk(2,'새봄학교에서 연락이 왔어요. 개학 전 운동장에서 학부모 안내를 해야 하는데, 비가 오면 망가지고 전기도 필요하고, 방송으로도 안내해야 한대요. 세 가지 다 챙겨야 해요. 예산은 7까지 쓸 수 있다고 하시네요.')}<div class="puzzle-hud"><span>예산 <b>${cost}/7</b></span><span>품목 <b>${items.length}/3</b></span><span>${['비','전원','안내'].map(x=>`<i class="need ${items.some(v=>v.tags.includes(x))?'met':''}">${x}</i>`).join('')}</span></div><div class="supply-grid">${SUPPLIES.map((x,i)=>`<button class="supply ${s.local.pick.includes(i)?'selected':''}" aria-pressed="${s.local.pick.includes(i)}" onclick="pick(${i},3)"><b>${x.icon}</b><strong>${x.name}</strong><small>${x.tags.join(' · ')} · ${x.cost}</small></button>`).join('')}</div><button class="btn full" onclick="checkMini()">이렇게 보내기 →</button><p class="hint">이야기용 예산이에요. 실제 조달 절차와는 다릅니다.</p>`}
const BOXES=[{label:'A',model:'HS-20',limit:'정상',detail:'모델 HS-20 · 방수 패킹 있음 · 시험 대상 HS-20'}, {label:'B',model:'HS-20',limit:'정상',detail:'모델 HS-20 · 방수 패킹 있음 · 시험 대상 HS-20'}, {label:'C',model:'HS-20',limit:'확인 필요',detail:'모델 HS-20 · 방수 패킹 있음 · 시험 대상 HS-10'}, {label:'D',model:'HS-20',limit:'정상',detail:'모델 HS-20 · 방수 패킹 있음 · 시험 대상 HS-20'}];
function badBox(){return s.seed%4}
function boxInfo(i){return BOXES[i===badBox()?2:0]}
function inspect(){return `${talk(0,'안내 센서 네 대가 똑같이 왔어요. 계약 모델은 HS-20인데, 라벨부터 하나씩 열어볼까요?')}<div class="box-grid">${[0,1,2,3].map(i=>`<button class="parcel ${s.local.open.includes(i)?'opened':''}" onclick="openBox(${i})"><span class="parcel-label">${'ABCD'[i]}</span><span class="parcel-art">▧</span><strong>${s.local.open.includes(i)?'라벨 확인함':'뜯어보기'}</strong><small>${s.local.open.includes(i)?boxInfo(i).detail:'모델이랑 시험 자료가 맞는지'}</small></button>`).join('')}</div><p class="section-title" style="margin-top:20px">추가로 살펴볼 상자는?</p><div class="row">${[0,1,2,3].map(i=>`<button class="btn ${s.local.selected===i?'':'outline'} small" onclick="selectBox(${i})" aria-pressed="${s.local.selected===i}">${'ABCD'[i]}번</button>`).join('')}</div><button class="btn full" onclick="checkMini()" ${s.local.selected===null?'disabled':''}>이 상자 다시 보기 →</button><p class="hint">이야기용 검수 장면이에요. 실제 검사 절차와는 달라요.</p>`}
function openBox(i){if(!isMini()||departmentForMini()<0)return;if(!s.local.open.includes(i))s.local.open.push(i);save();play();beep()}
function selectBox(i){if(!isMini())return;s.local.selected=i;save();play()}
const BLOCKS=[5,6,9];
function route(){return `${talk(1,'산업단지 가는 길, 다리 세 군데가 막혔어요. 창고에서 공장까지 잠긴 칸 피해서 이어 주세요.')}<div class="route-board">${Array.from({length:16},(_,i)=>`<button class="route-tile ${BLOCKS.includes(i)?'blocked':''} ${s.local.path.includes(i)?'active':''} ${i===s.local.path.at(-1)?'current':''}" onclick="walk(${i})" ${BLOCKS.includes(i)?'disabled':''} aria-label="${Math.floor(i/4)+1}행 ${i%4+1}열 ${i===0?'창고':i===15?'공장':BLOCKS.includes(i)?'침수':'길'}"><span>${i===0?'▣':i===15?'⚑':BLOCKS.includes(i)?'≈':s.local.path.includes(i)?'●':'·'}</span><small>${i===0?'창고':i===15?'공장':BLOCKS.includes(i)?'침수':''}</small></button>`).join('')}</div><p class="hint">옆 칸으로만 이동해요. 오른쪽 아래 공장까지.</p><div class="row"><button class="btn outline small" onclick="resetPuzzle()">다시 그리기</button><button class="btn" onclick="checkMini()" ${s.local.path.at(-1)!==15?'disabled':''}>이 경로로 넘기기 →</button></div><p class="hint">이야기용 도면이에요. 실제 배차랑은 달라요.</p>`}
const TESTS=[{name:'어두운 복도 실험',tag:'어둠',desc:'빛이 적어도 사람을 구분할까?',icon:'◐'}, {name:'빠르게 지나가기',tag:'속도',desc:'달리는 사람을 놓치지 않을까?',icon:'↝'}, {name:'비슷한 가방 들기',tag:'구분',desc:'가방과 사람을 헷갈리지 않을까?',icon:'▱'}, {name:'포스터 촬영',tag:'홍보',desc:'보기 좋은 제품 사진 남기기',icon:'▣'}];
function testLab(){return `${talk(2,'밝을 땐 잘 됐는데, 복도가 어두워지면 가방을 사람으로 본대요. 현장에서 해볼 시험 두 가지 골라 주세요.')}<div class="supply-grid">${TESTS.map((x,i)=>`<button class="supply ${s.local.pick.includes(i)?'selected':''}" onclick="pick(${i},2)" aria-pressed="${s.local.pick.includes(i)}"><b>${x.icon}</b><strong>${x.name}</strong><small>${x.desc}</small></button>`).join('')}</div><p class="hint">${s.local.pick.length}/2개 · 실험실만으로는 부족할 때가 있어요.</p><button class="btn full" onclick="checkMini()" ${s.local.pick.length!==2?'disabled':''}>시험 돌려보기 →</button>`}
const PLAN_BLOCKS=[1,5,7];
function pathGame(){return `${talk(0,'문화관 입구에서 홀까지 길이 필요해요. 기둥은 못 옮기고, 이 작은 도면에서는 일곱 칸 안에 이어 주세요.')}<div class="route-board blueprint">${Array.from({length:12},(_,i)=>`<button class="route-tile ${PLAN_BLOCKS.includes(i)?'blocked':''} ${s.local.path.includes(i)?'active':''} ${i===s.local.path.at(-1)?'current':''}" onclick="walk(${i})" ${PLAN_BLOCKS.includes(i)?'disabled':''} aria-label="도면 ${Math.floor(i/4)+1}행 ${i%4+1}열"><span>${i===0?'↗':i===11?'▣':PLAN_BLOCKS.includes(i)?'■':s.local.path.includes(i)?'●':'·'}</span><small>${i===0?'입구':i===11?'홀':PLAN_BLOCKS.includes(i)?'기둥':''}</small></button>`).join('')}</div><p class="hint">상하좌우로 이동 · ${s.local.path.length}/7칸</p><div class="row"><button class="btn outline small" onclick="resetPuzzle()">다시 그리기</button><button class="btn" onclick="checkMini()" ${s.local.path.at(-1)!==11?'disabled':''}>이 동선으로 넘기기 →</button></div><p class="hint">이야기용 작은 도면이에요. 실제 설계 기준이랑은 달라요.</p>`}
const ORDER=['불편한 점 먼저 듣기','작은 시제품 만들기','같이 써 보기','고친 뒤 확인하기'];
function orderGame(){return `${talk(1,'예약 화면엔 버튼만 많고, 어르신들은 어디 누를지 모르겠대요. 고치는 순서를 다시 맞춰 볼까요?')}<div class="sequence">${[0,1,2,3].map((_,i)=>`<div class="seq-slot"><b>${i+1}</b><span>${s.local.order[i]!==undefined?ORDER[s.local.order[i]]:'다음에 올 일'}</span></div>`).join('')}</div><div class="choice-stack">${[2,0,3,1].map(i=>`<button class="story-choice" onclick="orderPick(${i})" ${s.local.order.includes(i)?'disabled':''}><span>${ORDER[i]}</span><b>＋</b></button>`).join('')}</div><div class="row" style="margin-top:18px"><button class="btn outline small" onclick="resetPuzzle()">순서 비우기</button><button class="btn" onclick="checkMini()" ${s.local.order.length!==4?'disabled':''}>이 순서로 진행 →</button></div><p class="hint">순서만 맞춰 보는 일이에요. 실제 계약 절차랑은 달라요.</p>`}
function isMini(){return s?.phase==='play'&&(s.step===2||s.step===4)}
function pick(i,max){if(s.phase!=='play')return;const a=s.local.pick,k=a.indexOf(i);if(k>=0)a.splice(k,1);else if(a.length<max)a.push(i);else return toast(`최대 ${max}개까지 선택할 수 있어요. 하나를 다시 눌러 빼주세요.`);save();play();beep()}
function walk(i){if(!isMini())return;const k=DEPTS[departmentForMini()].kind,b=k==='route'?BLOCKS:PLAN_BLOCKS,n=k==='route'?16:12,a=s.local.path,prev=a.at(-1);if(i<0||i>=n||b.includes(i))return;if(a.length>1&&i===a.at(-2))a.pop();else if(!a.includes(i)&&Math.abs(Math.floor(i/4)-Math.floor(prev/4))+Math.abs(i%4-prev%4)===1)a.push(i);else return toast('현재 위치에서 바로 옆 칸을 골라주세요. 바로 전 칸을 누르면 되돌아갑니다.');save();play();beep()}
function orderPick(i){if(!isMini()||s.local.order.includes(i))return;s.local.order.push(i);save();play();beep()}
function resetPuzzle(){s.local.pick=[];s.local.path=[0];s.local.order=[];s.local.feedback='';save();play()}
function miniCheck(){const k=DEPTS[departmentForMini()].kind,l=s.local;if(k==='kit'){const x=l.pick.map(i=>SUPPLIES[i]);return x.length<=3&&x.reduce((a,b)=>a+b.cost,0)<=7&&['비','전원','안내'].every(tag=>x.some(v=>v.tags.includes(tag)))}if(k==='inspect')return l.selected===badBox();if(k==='route')return l.path.at(-1)===15;if(k==='test')return l.pick.length===2&&l.pick.includes(0)&&l.pick.includes(2);if(k==='path')return l.path.at(-1)===11&&l.path.length<=7;if(k==='order')return l.order.join(',')==='0,1,2,3';return false}
function checkMini(){if(!isMini())return;if(miniCheck())return completeMini(false);const k=DEPTS[s.dept].kind;const reasons={kit:'필요한 걸 다 못 챙겨서, 현장에서 추가 준비가 필요했어요.',inspect:'시험 자료가 다른 상자인 걸 놓쳐서, 다시 확인해야 했어요.',route:'이 경로로는 공장까지 못 가서, 운송 계획을 다시 짰어요.',test:'골란 시험만으로는 오류를 못 봐서, 한 번 더 돌려봐야 했어요.',path:'조건에 맞는 동선이 아니라서, 도면을 보완해야 했어요.',order:'고치기를 너무 먼저 해서, 불편한 점이 그대로 남았어요. 듣기 → 시제품 → 같이 써 보기 → 고치기 순으로 다시 맞춰야 해요.'};finish('한번 더 손봐야 했어요',reasons[k]+' 일정이 밀려 여유와 동료 신뢰가 조금 줄었어요. 이어지는 장면에도 영향이 남습니다.',{energy:-2,trust:-1,flag:'rework'},DEPTS[s.dept].source)}

function puzzleHint(){if(!isMini())return;const k=DEPTS[departmentForMini()].kind;const hints={kit:'보조 전원이랑 다기능 안내함 같이 고르면, 비·전원·안내를 7 안에 맞출 수 있어요.',inspect:`${'ABCD'[badBox()]}번 상자 라벨을 다시 봐요. 시험 대상 모델이 달라요.`,route:'맨 위부터 오른쪽 끝까지 간 다음, 오른쪽 가장자리를 따라 내려가면 돼요.',test:'어두운 복도랑 비슷한 가방 들기, 이 둘 골라 보세요.',path:'입구에서 아래로 두 칸, 오른쪽으로 세 칸이면 홀까지 이어져요.',order:'불편 듣기 → 작은 시제품 → 같이 써 보기 → 고치기, 이 순서예요.'};s.local.tool=true;s.local.feedback=hints[k];save();play()}
function teamFinish(){if(!isMini()||s.local.tries<2)return;completeMini(true)}
function completeMini(assisted){const id=departmentForMini(),d=DEPTS[id],texts={kit:'보낸 물건이 운동장에 도착했어요. 덮개 치고 전원 연결하니까, 안내 방송이 나가기 시작했습니다.',inspect:'시험 자료가 다른 상자 하나를 찾아냈어요. 확인 끝나고 현장으로 보낼 수 있게 됐습니다.',route:'물류 담당자랑 우회 경로를 맞춰 봤어요. 원자재 기다리던 공장에 다시 움직임이 생겼습니다.',test:'어두운 복도에서 같은 오류가 나왔어요. 작은 시험 덕에 고칠 부분이 보였습니다.',path:'누구나 지나갈 동선을 도면에 담았어요. 멋만 있는 입구보다, 발이 닿는 길이 먼저였습니다.',order:'먼저 불편한 점을 듣고, 작게 고쳐 봤더니 예약 화면이 한결 수월해졌습니다.'};const city=[0,0,0];city[id===2?1:id===4||id===5?2:0]=assisted?1:2;finish(assisted?'동료랑 같이 맞춰 봤어요':miniTitle(d.kind),texts[d.kind]+(assisted?' 동료가 마지막 고르기를 도왔어요. 다음엔 혼자서도 할 수 있을 것 같아요.':''),{energy:-1,trust:assisted?1:0,city,flag:'mini'+id,bag:id===2?'여유 물량':id===1?'검사 체크 노트':id===3?'현장 실험 노트':undefined},d.source)}
function lunch(){shell(title('동료 이야기','“오늘 점심, 같이 드실래요?”','오전 업무를 마치자 배가 고파졌습니다. 도현이 머뭇거리며 다가옵니다.')+`<div class="paper-body">${talk(1,'다들 척척 하는 것 같은데 저만 느린 것 같아요. 아까는 엉뚱한 파일을 회의 화면에 띄웠거든요… 고양이 사진이었어요.')}<div class="choice-stack">${choice('나도 오늘 헷갈렸던 일을 털어놓는다','서로의 실수를 나누기 · 신뢰 +2, 여유 +1',"lunchChoice(0)")}${choice('잠깐 바람 쐬고, 오후에 함께 보자고 한다','내 컨디션도 챙기기 · 여유 +3, 신뢰 +1',"lunchChoice(1)")}${choice('점심을 먹으며 다른 부서의 이야기를 듣는다','새 연결 만들기 · 신뢰 +1, 협업 카드 획득',"lunchChoice(2)")}</div></div>`)}
function lunchChoice(i){const o=[['고양이 사진 덕분에','회의가 아니라 점심자리에서 웃었습니다. 도현이 “다음엔 제가 도와줄게요”라고 말했습니다.',{trust:2,energy:1,flag:'friend'}],['쉬어도 이야기는 이어진다','산책하고 돌아와 동료의 파일을 함께 확인했습니다. 잠깐 쉬는 시간이 다음 일을 할 힘이 됐습니다.',{trust:1,energy:3}],['다른 층에 아는 사람이 생겼다','다른 부서 동료가 자신의 연락처를 건넸습니다. “혼자 끌어안지 말고 연락해요.”',{trust:1,bag:'협업 연락망',flag:'network'}]][i];if(o)finish(o[0],o[1],o[2],11)}
function transfer(){s.dept=s.first;s.route=[{dept:s.first,day:1}];s.phase='play';s.local=blank();eventOpen=true;save();render()}
function moveDept(){if(s.phase==='transfer')transfer()}
function crisis(){const covered=s.flags.rain||s.flags.harbor;const daysLeft=30-DAYS[s.step];const forecast=s.weather===0?'하천의 물이 불어나 운송 다리가 통제됐습니다.':'폭우로 야외 장비 설치와 배송이 동시에 밀렸습니다.';shell(title('돌발 사건','밤사이, 계획이 바뀌었다',forecast)+`<div class="paper-body">${talk(2,`개학까지 ${daysLeft}일 남았는데, 학교 개학 준비는 아직 다 끝나지 않았어요. 공장은 원자재를 기다리고 있고요. 시간이 촉박합니다. 한꺼번에 다 해결하긴 어렵습니다. 어떤 순서로 일정을 맞출까요?`)}${covered?`<div class="callback"><span>↶ 예전에 해둔 게 도움이 됨</span><p>${s.flags.harbor?'항구에서 받은 우회 연락처가 떠올랐어요.':'학교에서 적어 둔 비 대비 메모가 생각났어요.'}</p></div>`:''}<div class="choice-stack">${choice('현장에서 얻은 단서로 우회 계획을 세운다',covered?`남은 ${daysLeft}일 · 단서로 학교·공장 일정 맞추기`: '현장 탐색에서 우천 또는 물류 단서 필요',"crisisChoice(0)",!covered)}${choice('여유 물량과 협업망을 함께 사용한다',s.bag.includes('여유 물량')||s.trust>=4?`남은 ${daysLeft}일 · 동료 분담으로 공장 우선`: '여유 물량 카드 또는 동료 신뢰 4 필요',"crisisChoice(1)",!s.bag.includes('여유 물량')&&s.trust<4)}${choice('일정을 나누고, 먼저 열 곳부터 알린다',`남은 ${daysLeft}일 · 학교 먼저, 문화관은 조정`,"crisisChoice(2)")}</div><p class="hint">남은 ${daysLeft}일 안에서 무엇부터 맞출지 정해요. 골라도 게임은 계속 이어집니다.</p></div>`)}
function crisisChoice(i){if(i===0&&!(s.flags.rain||s.flags.harbor))return;if(i===1&&!s.bag.includes('여유 물량')&&s.trust<4)return;const o=[['현장 노트가 길이 되었다','며칠 전 적어 둔 메모가 위기 대응의 출발점이 됐습니다. 관계자들과 우회 계획을 조율해 두 곳의 준비를 이어갔습니다.',{city:[1,1,0],energy:-1,flag:'resilient'}],['전화 한 통의 거리','혼자 해결할 수 없던 일을 동료들이 나눠 맡았습니다. 확보된 여유 물량과 일정 조정으로 공장의 숨통이 트였습니다.',{city:[0,2,0],trust:-1,flag:'resilient'}],['순서를 바꾸는 용기','모든 일정을 지킨다고 약속하지 않았습니다. 학교부터 준비하고 문화관의 변경 일정을 솔직하게 안내했습니다.',{city:[2,0,0],energy:1,flag:'phased'}]][i];if(o)finish(o[0],o[1],o[2],2)}
const CALLS=[{name:'창업 2년 차 기업',say:'“제품은 만들었는데 공공기관에 어떻게 알리죠?”',answer:0},{name:'공공시장 진입을 준비하는 기업',say:'“어떤 제도를 먼저 알아봐야 할지 막막해요.”',answer:1},{name:'해외로 나가려는 기업',say:'“국내 공급 경험을 해외 공공시장으로 이어가고 싶어요.”',answer:2}];
const DESKS=['벤처나라 안내','공공조달 길잡이 상담','해외조달시장 진출 지원'];
function routing(){shell(title('안내 연결','기업 문의, 어디로 넘길까요','세 군데 사정이 달라요. 맞는 상담 창구를 골라 주세요.')+`<div class="paper-body">${talk(0,'우리가 전부 해결할 순 없어요. 대신 누구한테 연결하면 되는지는 찾을 수 있죠.')}<div class="calls">${CALLS.map((c,i)=>`<div class="call-card"><span class="label">전화 0${i+1}</span><h3>${c.name}</h3><p>${c.say}</p><label class="sr" for="call-${i}">${c.name} 안내 창구</label><select id="call-${i}" onchange="assignCall(${i},this.value)"><option value="">창구 고르기</option>${DESKS.map((x,j)=>`<option value="${j}" ${s.local.order[i]===j?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')}</div>${s.local.feedback?`<div class="feedback" role="status">${s.local.feedback}</div>`:''}<button class="btn full" onclick="submitCalls()" >연결 완료 →</button><p class="hint">일반적인 안내 연결이에요. 실제 자격은 제도마다 달라요.</p></div>`)}
function assignCall(i,v){if(s.step!==6||s.phase!=='play')return;s.local.order[i]=v===''?null:Number(v);save();play()}
function submitCalls(){if(s.step!==6||s.phase!=='play')return;const correct=CALLS.filter((c,i)=>c.answer===s.local.order[i]).length;const missed=3-correct;const detail=CALLS.map((c,i)=>`${c.name}: ${Number.isInteger(s.local.order[i])?DESKS[s.local.order[i]]:'미연결'} → ${c.answer===s.local.order[i]?'담당 창구에 연결됐습니다.':'재안내 필요. 적합한 창구는 '+DESKS[c.answer]+'입니다.'}`).join(' ');finish(missed?'기업 문의 일부를 다시 안내해야 합니다':'세 기업의 안내를 마쳤습니다',detail+(missed?' 잘못 연결하거나 미연결한 '+missed+'건을 동료가 재안내했습니다. 이후 대응에 쓸 시간과 신뢰가 줄었습니다.':' 각 기업이 다음 절차를 확인할 수 있게 됐습니다.'),{energy:-missed,trust:missed?-1:1,city:[0,correct===3?1:0,0],flag:missed?'misdirected':'callsComplete',bag:missed?undefined:'기업 지원 지도'},10)}
function project(){const daysLeft=30-DAYS[s.step];const schoolPrep=s.bag.includes('교실 현장 메모')||s.bag.includes('우천 대비 메모')||s.flags.rain;shell(title('선택 프로젝트','개학까지 손볼 한 곳','필수 업무는 돌아가고 있어요. 그래도 한 군데만 더 보강할 시간이 조금 생겼습니다.')+`<div class="paper-body">${talk(2,`꼭 해야 하는 과제는 아니에요. 개학까지 ${daysLeft}일 남았는데, 한 곳만 더 손보면 아이들·근로자·관람객이 조금 편해질 것 같아요. 어디에 힘을 쓸까요?`)}<div class="choice-stack">${choice('학교 운동장·개학 준비 장비를 점검한다',schoolPrep?'현장 메모 활용 · 학교 +2, 여유 −1':'설치 조건 다시 확인 · 학교 +1, 여유 −1',"projectChoice(0)")}${choice('문화관의 마지막 문턱을 확인한다',s.flags.access?'동선 스케치 활용 · 문화관 +2, 여유 −1':'입구 동선 다시 걷기 · 문화관 +1, 여유 −1',"projectChoice(1)")}${choice('공장의 작은 업체들을 한 번 더 연결한다',s.bag.includes('기업 지원 지도')?'기업 지원 지도 활용 · 산업단지 +1, 신뢰 +1':'상담 창구 안내 · 산업단지 +1, 신뢰 +1',"projectChoice(2)")}</div><p class="hint">하나만 골라도 충분해요. 앞에서 쌓은 메모·기록이 있으면 효과가 커져요.</p></div>`)}
function projectChoice(i){const schoolPrep=s.bag.includes('교실 현장 메모')||s.bag.includes('우천 대비 메모')||s.flags.rain;const o=[['개학 앞 마지막 점검',schoolPrep?'교실 전원·운동장 안내 장비를 현장에서 다시 맞췄습니다. 비 오는 날과 개학 첫날을 함께 상정해 보완했습니다.':'선생님·설치 담당자와 조건을 다시 확인했습니다. 완벽하진 않아도 개학 날 쓸 순서가 잡혔습니다.',{city:[schoolPrep?2:1,0,0],energy:-1,flag:'schoolPrep'},0],['마지막 문턱을 넘는 사람들',s.flags.access?'현장 동선 스케치를 다시 펼쳤습니다. 담당자와 보완 지점을 확인하자 문화관에 들어오는 길이 조금 더 넓어졌습니다.':'현장 담당자와 입구를 함께 걸었습니다. 새롭게 발견한 불편을 검토 요청에 담았습니다.',{city:[0,0,s.flags.access?2:1],energy:-1,flag:'inclusive'},4],['계약 이전에도 할 수 있는 일','작은 기업들이 필요한 상담 창구를 찾았습니다. 조달청의 일이 물건 구매 한 가지가 아니라는 것을 실감했습니다.',{city:[0,1,0],trust:1,flag:'bridge'},6]][i];if(o)finish(o[0],o[1],o[2],o[3])}
const OPS=[{name:'학교 설치팀 연결',desc:'수업 준비를 마무리',cost:2,city:[2,0,0]}, {name:'물류 공동 점검',desc:'공급 일정을 함께 조정',cost:2,city:[0,2,0]}, {name:'문화관 동선 점검',desc:'모두가 들어올 길 확인',cost:2,city:[0,0,2]}, {name:'세 곳에 운영 안내',desc:'시민에게 변경 사항 전달',cost:1,city:[1,1,1]}, {name:'동료와 합동 지원',desc:'협업으로 세 곳 보완',cost:2,city:[1,1,1],trust:4}];
function opBudget(){return 4+(s.trust>=4?1:0)+(s.energy>=5?1:0)}
function finalPlan(){const cost=s.local.pick.reduce((a,i)=>a+OPS[i].cost,0);shell(title('개학 전 밤','내일 문 여는 날','마지막으로 손볼 일을 고릅니다. 할 수 있는 만큼만 골라도 괜찮아요.')+`<div class="paper-body">${talk(1,s.flags.friend?'그날 점심에 제 얘기 들어줬잖아요. 오늘은 제가 같이할게요.':'완벽하지 않아도 괜찮아요. 할 수 있는 것부터 같이 골라 봐요.')}<div class="puzzle-hud"><span>할 일 예산 <b>${cost} / ${opBudget()}</b></span><span>신뢰 ${s.trust} · 여유 ${s.energy}</span></div><p class="hint">기본 4 + (신뢰 4↑ 1) + (여유 5↑ 1). 앞에서 쌓은 선택이 여기까지 이어져요.</p><div class="operation-list">${OPS.map((o,i)=>`<button class="story-choice ${s.local.pick.includes(i)?'selected':''}" onclick="pickOp(${i})" ${o.trust&&s.trust<o.trust?'disabled':''} aria-pressed="${s.local.pick.includes(i)}"><span>${s.local.pick.includes(i)?'✓ ':''}${o.name}</span><small>${o.desc} · 예산 ${o.cost}${o.trust?' · 신뢰 4 필요':''}</small><b>${o.cost}</b></button>`).join('')}</div><button class="btn full" onclick="submitOps()" ${!s.local.pick.length||cost>opBudget()?'disabled':''}>이대로 내일 준비 →</button>${cost>opBudget()?'<p class="hint" style="color:var(--red)">예산을 넘었어요. 다시 누르면 선택이 빠져요.</p>':''}</div>`)}
function pickOp(i){if(s.phase!=='play'||s.step!==8||!OPS[i]||(OPS[i].trust&&s.trust<OPS[i].trust))return;pick(i,5)}
function submitOps(){if(s.phase!=='play'||s.step!==8)return;const cost=s.local.pick.reduce((a,i)=>a+OPS[i].cost,0);if(!s.local.pick.length||cost>opBudget())return;const city=[0,0,0];s.local.pick.forEach(i=>OPS[i].city.forEach((n,j)=>city[j]+=n));finish('한 사람의 업무가, 여러 사람의 내일로',`${s.local.pick.map(i=>OPS[i].name).join(', ')}. 각자의 역할을 나누자 마지막 준비가 움직이기 시작했습니다.`,{city,energy:-1},11)}
function finale(){shell(title('마지막 선택','퇴근길에, 잠깐 들를까요?','서류는 닫았습니다. 이제 그 서류가 닿은 곳을 보러 갑니다.')+`<div class="paper-body">${talk(2,s.flags.friend?`한 달 동안 수고 많았어요, ${esc(s.name)}님. 도현이도 같이 오라고 했어요. 어디부터 볼까요?`:`한 달 동안 수고 많았어요. 오늘은 현장 소리가 서류보다 먼저일 거예요. 어디부터 보고 가실래요?`)}<div class="choice-stack">${choice('학교 앞에서 첫 수업의 소리를 듣는다','새봄학교의 결말 보기',"finaleChoice(0)")}${choice('산업단지의 퇴근 불빛을 바라본다','공장 사람들의 결말 보기',"finaleChoice(1)")}${choice('문화관의 문을 열고 들어간다','문화관의 결말 보기',"finaleChoice(2)")}</div></div>`)}
function finaleCoda(i){const bits=[];if(i===0){if(s.flags.rain||s.bag.includes('우천 대비 메모'))bits.push('젖은 현관 옆에 남겨 둔 우천 메모가 아직 책상 위에 있었습니다.');if(s.flags.friend)bits.push('도현이 옆에서 “우리도 이 소리에 이름 하나 붙인 셈이죠?”라고 웃었습니다.')}if(i===1){if(s.flags.harbor||s.bag.includes('대체 물류 연락망'))bits.push('막혔던 길 대신 썼던 우회 연락처가 담당자 손에 남아 있었습니다.');if(s.bag.includes('여유 물량'))bits.push('예비 물량 덕분에 멈추던 라인 중 하나가 다시 돌아갔습니다.');if(s.flags.friend)bits.push('도현에게 “오늘 퇴근은 늦어도 괜찮대요”라는 메시지가 왔습니다.')}if(i===2){if(s.flags.access||s.bag.includes('현장 동선 스케치'))bits.push('스케치에 적어 둔 문턱이 하나씩 낮아진 자국이 보였습니다.');if(s.trust>=5)bits.push('서윤 선배가 “처음 들어온 길이, 이제는 누군가의 일상이 됐네요”라고 말했습니다.');}return bits.join(' ')}
function cityEnding(i){const n=s.city[i];return [n>=4?'창문 너머로 수업이 시작되는 소리가 들립니다. 당신이 챙긴 조건들이 이제 아이들의 평범한 하루가 됐습니다.':n>=2?'몇 교실부터 새 준비가 시작됐습니다. 아직 남은 일이 있지만, 첫 수업의 방향은 잡혔습니다.':'학교의 준비는 조금 더 시간이 필요합니다. 당신의 인수인계 기록이 다음 담당자의 시작점이 됩니다.',n>=4?'작업을 마친 사람들이 공장을 나섭니다. 누군가에게는 원자재였고, 누군가에게는 오늘 하루의 일자리였습니다.':n>=2?'일부 생산라인에 다시 불이 들어왔습니다. 다음 입고를 기다리며 준비를 이어갑니다.':'공장에는 아직 조정할 공급 일정이 남았습니다. 연결해 둔 연락망은 다음 주에도 이어질 겁니다.',n>=4?'누군가가 유모차를 밀고 문턱을 넘습니다. 문이 열리는 순간, 도면의 선이 사람의 길이 됐습니다.':n>=2?'문화관이 작은 공간부터 문을 열었습니다. 나머지 공간은 더 꼼꼼하게 준비하기로 했습니다.':'문화관의 개관은 조금 미뤄졌습니다. 발견한 불편을 남긴 덕분에 다음 검토는 더 나아질 겁니다.'][i]}
function finaleChoice(i){if(s.step!==9||s.phase!=='play'||i<0||i>2)return;s.flags.focus=i;const epilogue=finaleCoda(i);finish(['수업이 시작되는 소리','공장에 남은 불빛','누구나 들어오는 문'][i],cityEnding(i)+(epilogue?' '+epilogue:''),{},i===0?0:i===1?2:4)}
function endingEcho(){const lines=[];const n=esc(s.name);if(s.flags.school||s.bag.includes('교실 현장 메모'))lines.push(`새봄학교에서: “전원·설치 조건 맞춰 준 ${n} 담당, 개학 전에 다시 연락드릴게요.”`);else if(s.flags.harbor||s.bag.includes('대체 물류 연락망'))lines.push('산업단지 담당자: “물량·일정 맞춰 준 덕에 라인이 멈추지 않았습니다. 고마워요.”');else if(s.flags.access)lines.push('문화관 담당자: “들어오는 길부터 봐 준 게, 막연한 도면이 아니라 사람 얘기가 됐어요.”');if(s.flags.friend)lines.push(`도현: “${n} 선배, 그날 점심 때문에 다음 장면도 같이 버틸 수 있었어요.”`);else if(s.trust>=5)lines.push('서윤 선배: “전화 한 통 고르는 것도 어려웠는데, 지금은 현장부터 떠올리게 됐네요.”');else if(s.trust>=3)lines.push('서윤 선배: “완벽하지 않아도 연결은 됐습니다. 다음 달도 천천히 가요.”');if(s.flags.callsComplete||s.bag.includes('기업 지원 지도'))lines.push('문의하던 기업: “어디로 가야 할지 몰랐는데, 안내해 준 창구에서 다음 절차를 알게 됐어요.”');if(s.visits.length){const p=PLACES[s.visits[0]];if(p)lines.push(`${p.name}에서 들었던 말이 떠올랐습니다. ${p.quote}`);}if(s.bag.length>=3)lines.push(`책상 위 메모 ${s.bag.length}장 — ${s.bag.slice(-2).map(esc).join(', ')}. 숫자가 아니라 사람 이름이 적혀 있었습니다.`);const uniq=[];for(const L of lines)if(!uniq.includes(L))uniq.push(L);return uniq.slice(0,3)}
function endingLetters(){return endingEcho().map(t=>`<p>${t}</p>`).join('')}
function result(){const e=s.log.at(-1),src=SOURCES[e.source];const fin=s.step===9;const outro=fin?(s.flags.friend?talk(1,'이제 엔딩만 보면 돼요. 긴장하지 말고, 우리가 남긴 장면부터 떠올려 봐요.'):talk(0,'한 달의 선택이 여기까지 이어졌습니다. 마지막은 도시가 어떻게 바뀌었는지 보며 마무리해요.')):'';shell(title(fin?'마지막 이야기': '오늘의 기록',e.title,fin?'퇴근길에 고른 한 장면이, 당신의 이름과 붙어 기록됩니다.':'고른 게 기록으로 남고, 다음 장면에 영향을 줘요.')+`<div class="paper-body"><div class="story-result">${talk(e.step===3?1:2,e.text)}</div>${outro}<div class="effect-chips">${effectText(e.effect)}</div>${fin?'':`<details class="learning"><summary>이 장면과 관련된 조달청 이야기</summary><p>${src.fact}</p><a href="${src.url}" target="_blank" rel="noopener noreferrer">${src.title} ↗</a><p class="fine">참고용 안내이며, 사건과 수치는 이야기를 위한 설정입니다.</p></details>`}<button class="btn full" onclick="advance()">${fin?'엔딩 보기 →':'다음 장면으로 →'}</button></div>`)}
function effectText(e){let t=[];if(e.energy)t.push(`여유 ${e.energy>0?'+':''}${e.energy}`);if(e.trust)t.push(`동료 신뢰 ${e.trust>0?'+':''}${e.trust}`);if(e.city)e.city.forEach((n,i)=>{if(n)t.push(`${['학교','산업단지','문화관'][i]} ${n>0?'+':''}${n}`)});if(e.bag)t.push(`${e.bag} 획득`);return t.map(x=>`<span class="chip">${esc(x)}</span>`).join('')}
function endTitle(){const lit=s.city.filter(n=>n>=4).length;return lit===3?'세 곳의 불을 다시 켠 사람':s.trust>=6?'사람과 사람 사이를 이은 사람':s.flags.inclusive?'누구도 문밖에 두지 않은 사람':s.flags.pilot?'새로운 가능성을 시험한 사람':'다음 이야기를 남긴 사람'}
function ending(){pauseAuto();closeModal();setChrome('focus');const lit=s.city.filter(n=>n>=4).length;const names=s.route.map(x=>DEPTS[x.dept].name).join(' → ');const echoes=endingEcho();$('app').innerHTML=`<section class="center wide-end screen screen-end"><div class="ending-heading"><span class="label">DAY 30 / 당신의 첫 발령 이야기</span><h1>${esc(s.name)}님은,<br>${endTitle()}.</h1><p>${DEPTS[s.first].name}에서 남긴 ${s.log.length}번의 선택 · ${names}</p></div><div class="city-strip city-strip-end">${cityArt()}</div><div class="ending-body"><div class="row space"><span class="seal">첫 시즌 완료</span><span class="muted">도시 ${lit}/3곳 활기 · 동료 신뢰 ${s.trust}/8</span></div><p class="ending-lead">${cityEnding(Number.isInteger(s.flags.focus)?s.flags.focus:0)}</p>${echoes.length?`<div class="ending-echo"><span class="label">돌아온 말</span>${endingLetters()}</div>`:''}<div class="ending-scenes">${CITY_SITES.map((n,i)=>`<div><span class="label">0${i+1} / ${n}</span><h3>${s.city[i]>=4?'일상이 돌아왔습니다':s.city[i]>=2?'변화가 시작됐습니다':'다음 이야기가 남았습니다'}</h3><p>${cityEnding(i)}</p></div>`).join('')}</div><div class="line"></div><h3>우연히 받은 발령, 내가 만든 연결</h3><div class="stamp-row">${s.route.map(x=>`<div class="department-stamp"><b>${DEPTS[x.dept].icon}</b><span>${DEPTS[x.dept].name}</span><small>DAY ${x.day}</small></div>`).join('')}</div><p class="muted" style="font-size:13px">이번 시즌은 한 부서에서 완주했습니다. 새 게임을 시작하면 다시 랜덤 발령받아 다른 부서의 이야기를 만날 수 있습니다.</p><div class="row" style="margin-top:26px"><button class="btn" onclick="newGame()">다른 발령으로 다시 시작 ↗</button><button class="btn outline" onclick="downloadReport()">이야기 기록 저장</button><button class="btn outline" onclick="showLog()">내 선택 돌아보기</button></div></div></section>`}
function downloadReport(){const text=`오늘부터 조달청 — 첫 발령, 그다음 이야기\n${s.name} / ${endTitle()}\n부서: ${s.route.map(x=>DEPTS[x.dept].name).join(' → ')}\n모든 사건과 수치는 가상입니다.\n\n`+s.log.map(e=>`DAY ${e.day} · ${e.title}\n${e.text}`).join('\n\n');const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='오늘부터_조달청_나의이야기.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('이야기 기록을 저장했습니다.')}
function goHome(){if(s&&!home)save();landing();window.scrollTo({top:0,behavior:'instant'})}
function showLog(){pauseAuto();modal('내 선택이 만든 이야기',s?.log?.length?`<ul class="report-list">${s.log.map(e=>`<li><span class="chip">DAY ${e.day} · ${DEPTS[e.dept].name}</span><h3 style="font-size:17px;margin-top:10px">${e.title}</h3><p>${e.text}</p></li>`).join('')}</ul>`:'<p>첫 선택부터 이곳에 이야기가 쌓입니다.</p>')}
function showSources(){pauseAuto();modal('조달청 탐험 노트',`<p>조직·업무·정책 안내를 바탕으로 소재를 구성했습니다. 사건과 인물, 부서의 협업 방식, 게임 규칙은 창작입니다.</p>${SOURCES.map(x=>`<div class="badge"><h3>${x.title}</h3><p>${x.fact}</p><a style="font-size:12px" href="${x.url}" target="_blank" rel="noopener noreferrer">공식 자료 읽기 ↗</a></div>`).join('')}<p class="fine">확인일: 2026.11.11. 공개 업무·정책 페이지 중심으로 조사했습니다. 사이트 전체나 비공개 자료를 수집했다는 의미가 아닙니다. 과거 연도 정책과 현재 절차는 구분해야 합니다.</p>`)}
function showGuide(){pauseAuto();modal('플레이 안내',`<div class="badge"><h3>발령은 랜덤</h3><p>6개 부서 중 한 곳에서 시작해요. 첫 발령은 한 번만 다시 뽑을 수 있고, 한 시즌 내내 그 부서 이야기를 이어 가요.</p></div><div class="badge"><h3>장면마다 다른 일</h3><p>대화, 현장 나가기, 손으로 맞춰 보기, 점심 이야기, 돌발 상황까지 이어집니다.</p></div><div class="badge"><h3>예전 선택이 돌아와요</h3><p>현장에서 메모해 둔 게 나중에 다른 길을 열어 줄 수 있어요. 동료 신뢰와 여유는 마지막 밤 계획에도 반영돼요.</p></div><div class="badge"><h3>틀려도 이야기는 계속</h3><p>현장 일은 다시 고를 수 있어요. 한번 어긋나면 여유가 줄지만 다음 장면으로 넘어갑니다. 엔딩은 점수표가 아니라 바뀐 도시 모습이에요.</p></div><p class="fine">자동 진행: 대화·선택을 동료가 대신 합니다. 막히는 장면은 도와줘요. 시간 제한 없음 · 브라우저에 자동 저장</p><button class="btn full" onclick="closeModal()">알겠어요 →</button>`)}
function showAbout(){pauseAuto();modal('첫 발령, 그다음 이야기',`<p>조달청의 여러 역할을 하나의 가상 도시 이야기로 경험하는 비공식 창작 게임입니다. 실제 조달청 서비스가 아니며, 공무원의 실제 권한·인사·계약 절차를 재현하지 않습니다.</p><p>게임 화면·도시 그림·사건·프로그램은 새로 제작했습니다. 사용자가 제공한 조달청 로고와 나르미·달이 이미지를 HTML에 포함했습니다. 외부 파일을 불러오지 않고 실행되며 실시간 AI 연결이나 개인정보 전송은 없습니다. 생성형 AI를 자료 정리와 기획·코딩 보조에 활용했습니다.</p><p>이번 버전은 반복 업무를 이야기·탐색·퍼즐·관계·선택으로 교체하고 한 시즌 한 부서로 진행합니다. 이전 부서 이동 화면에 저장된 기록도 자동으로 이어집니다. 구버전 저장 기록은 삭제하지 않으며 새 이야기의 저장 공간은 별도로 사용합니다.</p><button class="btn outline" onclick="closeModal();showSources()">공식 자료와 참고 범위 확인 →</button>`)}
document.addEventListener('keydown',e=>{if(!$('overlay').firstElementChild)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const a=Array.from($('overlay').querySelectorAll('button,a,input,select,[tabindex="0"]')).filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===a[0]){e.preventDefault();a.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===a.at(-1)){e.preventDefault();a[0].focus()}}});
landing();
